 parent=section['parent'];search=section['search'];actions=section.get('diagnostic_actions',{});masked=actions.get('masked_members',[]);removed=actions.get('removed_groups',[]);excluded=actions.get('excluded_evidence_rows',[]);diagnostic=search['diagnostic_exclusion'];assert type(diagnostic) is bool;assert parent['reference_package_sha256']==search['reference_package_sha256']==current, 'Actual parent/search package binding differs';assert parent['policy_sha256']==BINDING['policies'][parent['policy_id']]
