 assert len(actual_groups)==len(expected['groups'])
 selected=[g for g in section['groups'] if section['compatible_groups']==[g['group']]];gv=dict(assigned=section['genomovar_id'],compatible=section['compatible_groups'],incomplete=section['incomplete_groups'],reasons=reasons,member_af_pass=bool(selected) and not selected[0]['below_member_af'])
 if diagnostic:gv['diagnostic_would_assign']=section['diagnostic_would_assign_genomovar_id']
 source=(next((g for g,n in names.items() if n==source_group),source_group) if source_group else None);assigned=gv.get('diagnostic_would_assign') if diagnostic else gv['assigned'];rec=dict(record_id=record_id,dataset=dataset,source_group=source,self_member=self_member,singleton_source=singleton_source,assigned_singleton=bool(assigned) and len(groups[assigned])==1,diagnostic=diagnostic,masked_members=masked,removed_groups=removed,parent=dict(status=parent['status'],species_id=parent['species_id'],subspecies_id=parent['subspecies_id'],call_basis=parent_basis),gv=gv);category,violations=None,[]  # Actual scorer record is retained;frozenstep9 performs scoring.
 return dict(record=rec,category=category,violations=violations,model_differences=differences,model_expected=expected,model_diagnostic_expected=diagnostic_expected,model_context=ctx,oracle_package_bridge=dict(actual_package=current,source_package=c.P3.PACKAGE,source_conversion_hash_checked=True,actual_parent_search_bindings_checked_before_alias=True,all_25_173_definition_identities_checked=True),raw_member_rows=raw)
